:root {
  --bg: #1e1e2f;
  --card-bg: #2a2a40;
  --text: #f0f0f5;
  --text-muted: #b0b0c0;
  --accent: #7c6ff0;
  --accent-hover: #9a8ff5;
  --accent-pressed: #5a4fcf;
  --swatch-radius: 12px;
  --font: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--bg);
  font-family: var(--font);
  font-size: 16px;
  color: var(--text);
  padding: 16px;
}

.card {
  background: var(--card-bg);
  border-radius: 24px;
  padding: 32px 24px;
  max-width: 600px;
  width: 100%;
  box-shadow: 0 20px 40px rgba(0, 0, 0, 0.4);
  text-align: center;
}

h1 {
  font-size: 2rem;
  font-weight: 700;
  letter-spacing: -0.02em;
  margin-bottom: 8px;
}

.subtitle {
  color: var(--text-muted);
  font-size: 1rem;
  margin-bottom: 32px;
}

.palette {
  display: flex;
  flex-wrap: wrap;
  gap: 16px;
  justify-content: center;
  margin-bottom: 32px;
}

.swatch {
  flex: 1 1 90px;
  min-width: 80px;
  max-width: 110px;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 8px;
}

.color-box {
  width: 100%;
  aspect-ratio: 1 / 1;
  border-radius: var(--swatch-radius);
  border: 3px solid transparent;
  transition: border-color 0.2s, transform 0.2s;
  position: relative;
}

.color-box.locked {
  border-color: var(--accent);
}

.hex-code {
  font-size: 0.9rem;
  font-weight: 600;
  letter-spacing: 0.03em;
  text-transform: uppercase;
  color: var(--text-muted);
  user-select: all;
}

.lock-btn {
  background: transparent;
  border: 2px solid var(--text-muted);
  border-radius: 50%;
  width: 32px;
  height: 32px;
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  color: var(--text-muted);
  font-size: 1rem;
  transition: background 0.2s, border-color 0.2s, color 0.2s;
  padding: 0;
  line-height: 1;
}

.lock-btn:hover {
  border-color: var(--accent);
  color: var(--accent);
}

.lock-btn:focus-visible {
  outline: 3px solid var(--accent);
  outline-offset: 2px;
}

.lock-btn[aria-pressed="true"] {
  background: var(--accent);
  border-color: var(--accent);
  color: #fff;
}

.lock-btn:active {
  transform: scale(0.9);
}

.generate-btn {
  background: var(--accent);
  color: #fff;
  border: none;
  border-radius: 12px;
  padding: 14px 32px;
  font-size: 1.1rem;
  font-weight: 600;
  font-family: inherit;
  cursor: pointer;
  transition: background 0.2s, transform 0.1s;
  width: 100%;
  max-width: 320px;
}

.generate-btn:hover {
  background: var(--accent-hover);
}

.generate-btn:focus-visible {
  outline: 3px solid var(--accent);
  outline-offset: 3px;
}

.generate-btn:active {
  background: var(--accent-pressed);
  transform: scale(0.97);
}

@media (max-width: 400px) {
  .card {
    padding: 24px 16px;
  }
  .palette {
    gap: 10px;
  }
  .swatch {
    flex: 1 1 70px;
    min-width: 60px;
  }
  .hex-code {
    font-size: 0.8rem;
  }
}

const paletteEl = document.getElementById('palette');
const generateBtn = document.getElementById('generate');

let colors = [];
let locked = [false, false, false, false, false];

function hslToHex(h, s, l) {
  s /= 100;
  l /= 100;
  const a = s * Math.min(l, 1 - l);
  const f = n => {
    const k = (n + h / 30) % 12;
    const color = l - a * Math.max(Math.min(k - 3, 9 - k, 1), -1);
    return Math.round(255 * color).toString(16).padStart(2, '0');
  };
  return `#${f(0)}${f(8)}${f(4)}`;
}

function generatePalette() {
  const baseHue = Math.random() * 360;
  const scheme = Math.random() > 0.5 ? 'analogous' : 'split';
  const newColors = [];
  for (let i = 0; i < 5; i++) {
    if (locked[i]) {
      newColors.push(colors[i]);
    } else {
      let hue;
      if (scheme === 'analogous') {
        hue = (baseHue + (i - 2) * 30 + (Math.random() * 20 - 10)) % 360;
      } else {
        const offsets = [0, 150, 210, 30, 180];
        hue = (baseHue + offsets[i] + (Math.random() * 20 - 10)) % 360;
      }
      if (hue < 0) hue += 360;
      const sat = 60 + Math.random() * 30;
      const light = 40 + Math.random() * 30;
      newColors.push(hslToHex(hue, sat, light));
    }
  }
  colors = newColors;
  render();
}

function render() {
  paletteEl.innerHTML = '';
  colors.forEach((hex, i) => {
    const swatch = document.createElement('div');
    swatch.className = 'swatch';

    const box = document.createElement('div');
    box.className = 'color-box' + (locked[i] ? ' locked' : '');
    box.style.backgroundColor = hex;

    const hexLabel = document.createElement('span');
    hexLabel.className = 'hex-code';
    hexLabel.textContent = hex;

    const lockBtn = document.createElement('button');
    lockBtn.className = 'lock-btn';
    lockBtn.setAttribute('aria-pressed', locked[i]);
    lockBtn.setAttribute('aria-label', locked[i] ? 'Unlock color' : 'Lock color');
    lockBtn.textContent = locked[i] ? '🔒' : '🔓';
    lockBtn.addEventListener('click', () => {
      locked[i] = !locked[i];
      lockBtn.setAttribute('aria-pressed', locked[i]);
      lockBtn.setAttribute('aria-label', locked[i] ? 'Unlock color' : 'Lock color');
      lockBtn.textContent = locked[i] ? '🔒' : '🔓';
      box.classList.toggle('locked', locked[i]);
    });

    swatch.appendChild(box);
    swatch.appendChild(hexLabel);
    swatch.appendChild(lockBtn);
    paletteEl.appendChild(swatch);
  });
}

generateBtn.addEventListener('click', generatePalette);

// Initial palette
generatePalette();
